import collections
import matplotlib.pyplot as plt

def task_func(data):
    if not data:
        return None

    student_scores = collections.defaultdict(list)
    for entry in data:
        for student, score in entry.items():
            if score is not None:
                if score < 0:
                    raise ValueError("Negative scores are not allowed.")
                student_scores[student].append(score)

    avg_scores = {}
    for student, scores in student_scores.items():
        if scores:
            avg_scores[student] = sum(scores) / len(scores)

    fig, ax = plt.subplots()

    students = list(avg_scores.keys())
    averages = list(avg_scores.values())

    if students:
        colors = ['red', 'yellow', 'green', 'blue', 'purple']
        bar_colors = [colors[i % len(colors)] for i in range(len(students))]
        ax.bar(students, averages, color=bar_colors)

    ax.set_xlabel('Student')
    ax.set_ylabel('Average Score')
    ax.set_title('Average Student Scores')

    return ax

